package ktrapic.datagen

/**
 * Generates the runtime API's Kotlin sources from the game data. The output is already in ktfmt's
 * format, so the committed files stay unchanged by formatting and can be compared byte for byte.
 */
object RuntimeGenerator {
  private const val HEADER =
      "// Generated by //tools/datagen from runtime/data. Do not edit; regenerate instead.\n\n" +
          "package ktrapic\n"

  /** The generated files, by name, in the `ktrapic` package directory. */
  fun generate(enums: LogicEnums, typing: Typing): Map<String, String> {
    val unknown = typing.operandEnums.filter { it !in enums.enums }
    require(unknown.isEmpty()) { "operand enums missing from the data: $unknown" }
    val logicTypes = requireNotNull(enums.enums["LogicType"]) { "the data has no LogicType" }
    val unknownBooleans = typing.booleanLogicTypes.filter { it !in logicTypes }
    require(unknownBooleans.isEmpty()) { "Boolean logic types not in LogicType: $unknownBooleans" }
    return mapOf(
        "GeneratedEnums.kt" to enumsFile(enums, typing),
        "GenericDevice.kt" to
            deviceFile(
                logicTypes.keys,
                typing.booleanLogicTypes.toSet(),
                enums.enums["LogicSlotType"]?.keys.orEmpty(),
                typing,
            ),
    )
  }

  /** As above, plus the typed device API for [prefabs], grouped by [grouping]. */
  fun generate(
      enums: LogicEnums,
      typing: Typing,
      prefabs: Prefabs,
      grouping: Grouping,
  ): Map<String, String> {
    val logicTypes = requireNotNull(enums.enums["LogicType"]) { "the data has no LogicType" }
    val unknown = prefabs.prefabs.flatMap { it.logic.keys }.toSet() - logicTypes.keys
    require(unknown.isEmpty()) { "prefab logic types not in LogicType: $unknown" }
    val slotLogicTypes = enums.enums["LogicSlotType"]?.keys.orEmpty()
    val unknownSlot =
        (prefabs.slotKinds.values.flatten() +
                typing.booleanSlotLogicTypes +
                typing.slotReadsAlways +
                typing.slotWrites.values.flatten() +
                typing.thingSlotReadsAlways +
                typing.thingSlotReadsByKind.values.flatten())
            .toSet() - slotLogicTypes
    require(unknownSlot.isEmpty()) { "slot logic types not in LogicSlotType: $unknownSlot" }
    // A kind the prefab data lacks is a misspelling, and its reads would reach no slot.
    val unknownKinds = typing.thingSlotReadsByKind.keys - prefabs.slotKinds.keys
    require(unknownKinds.isEmpty()) { "thing slot kinds not in the prefab data: $unknownKinds" }
    // The game decides slot writes by the slot's class, so a kind must be one; some have no
    // prefab yet, so the prefab data's kinds can't be the check.
    val writeKinds = typing.slotWrites.keys - "any"
    val unknownWriteKinds = writeKinds - enums.enums["SlotClass"]?.keys.orEmpty()
    require(unknownWriteKinds.isEmpty()) { "slot write kinds not in SlotClass: $unknownWriteKinds" }
    val anyWrites = typing.slotWrites["any"].orEmpty().toSet()
    val kindWrites = writeKinds.flatMap { typing.slotWrites.getValue(it) }.toSet()
    require(anyWrites == kindWrites) {
      "slot writes for any ($anyWrites) aren't those of every kind together ($kindWrites)"
    }
    val enumNames = enums.enums.keys.map { identifier(it) }.toSet()
    val substances = LogicViews.substances(logicTypes.keys).toSet()
    return generate(enums, typing) +
        (ViewsGenerator.FILE to ViewsGenerator.generate(logicTypes.keys, typing, prefabs)) +
        PrefabGenerator.generate(prefabs, grouping, enumNames, typing, substances)
  }

  private fun enumsFile(enums: LogicEnums, typing: Typing): String = buildString {
    append(HEADER)
    for ((name, entries) in enums.enums) {
      append('\n')
      if (name in typing.operandEnums) {
        append("/** The game's $name operands. */\n")
        append("enum class ${identifier(name)}(val value: Int) {\n")
        val lines = entries.map { (entry, value) -> "  ${identifier(entry)}($value)" }
        append(lines.joinToString(",\n", postfix = ",\n"))
        append("}\n")
      } else {
        append("/** The game's $name values. */\n")
        append("object ${identifier(name)} {\n")
        for ((entry, value) in entries) {
          append("  const val ${identifier(entry)}: Double = $value.0\n")
        }
        append("}\n")
      }
    }
  }

  private fun deviceFile(
      logicTypes: Collection<String>,
      booleans: Set<String>,
      slotLogicTypes: Collection<String>,
      typing: Typing,
  ): String = buildString {
    append(HEADER)
    append('\n')
    append("/**\n")
    append(" * Every logic type the game has, as a property. A device has only some of them; ")
    append("reading or writing\n")
    append(" * one it lacks is an error on the chip.\n")
    append(" */\n")
    append("abstract class GenericDevice internal constructor() {\n")
    val substances = LogicViews.substances(logicTypes).toSet()
    val views = logicTypes.mapNotNull { LogicViews.viewOf(it, substances) }.distinct()
    // LogicType.None is the "no logic type" operand, not a property; a view's logic types are
    // reached through the view.
    val flat = logicTypes.filter { it != "None" && LogicViews.viewOf(it, substances) == null }
    for ((index, logicType) in flat.withIndex()) {
      if (index > 0) append('\n')
      // A device's prefab is a Prefab, compared with prefabs rather than used as a number.
      if (logicType == "PrefabHash") {
        append("  val PrefabHash: Prefab\n")
        append("    get() = intrinsic()\n")
        continue
      }
      val type = if (logicType in booleans) "Boolean" else "Double"
      append("  var ${identifier(logicType)}: $type\n")
      append("    get() = intrinsic()\n")
      append("    set(value) = intrinsic()\n")
    }
    // Unchecked, as the flat logic types are: every view, with its settable members.
    for (view in views) {
      append('\n')
      append("  val $view: ${ViewsGenerator.viewType(view, listOf("any"))}\n")
      append("    get() = intrinsic()\n")
    }
    if (slotLogicTypes.isNotEmpty()) {
      append('\n')
      append("  /** The device's slots, by number. */\n")
      append("  val slots: Slots<Slot>\n")
      append("    get() = intrinsic()\n")
    }
    append("}\n")
    if (slotLogicTypes.isEmpty()) return@buildString
    // The game lets a program write only a few slot logic types, whatever the slot.
    val writes = typing.slotWrites["any"].orEmpty().toSet()
    append('\n')
    append("/**\n")
    append(" * A slot of a device whose prefab isn't known, with every slot logic type the game ")
    append("has. A slot can\n")
    append(" * read only some of them, and the game lets a program write only ")
    append("${writes.sorted().joinToString()}.\n")
    append(" */\n")
    append("class Slot internal constructor() : DeviceSlot() {\n")
    for ((index, logicType) in slotLogicTypes.filter { it != "None" }.withIndex()) {
      if (index > 0) append('\n')
      val type = if (logicType in typing.booleanSlotLogicTypes) "Boolean" else "Double"
      val keyword = if (logicType in writes) "var" else "val"
      append("  $keyword ${identifier(logicType)}: $type\n")
      append("    get() = intrinsic()\n")
      if (logicType in writes) append("    set(value) = intrinsic()\n")
    }
    append("}\n")
  }

  private val KEYWORDS =
      setOf(
          "as",
          "break",
          "class",
          "continue",
          "do",
          "else",
          "false",
          "for",
          "fun",
          "if",
          "in",
          "interface",
          "is",
          "null",
          "object",
          "package",
          "return",
          "super",
          "this",
          "throw",
          "true",
          "try",
          "typealias",
          "typeof",
          "val",
          "var",
          "when",
          "while",
      )
  private val IDENTIFIER = Regex("[A-Za-z_][A-Za-z0-9_]*")

  private fun identifier(name: String): String {
    require(IDENTIFIER.matches(name)) { "not a Kotlin identifier: $name" }
    return if (name in KEYWORDS) "`$name`" else name
  }
}
